use std :: sync :: { Arc , Mutex } ; use clap :: error :: ErrorKind ; use clap :: { Parser , Subcommand } ; use forge_api :: { AgentInfo , Model , Template } ; use forge_domain :: UserCommand ; use strum :: { EnumProperty , IntoEnumIterator } ; use strum_macros :: { EnumIter , EnumProperty } ; use crate :: info :: Info ; use std :: fmt :: Display ; use colored :: Colorize ; use console :: strip_ansi_codes ; use forge_api :: { AnyProvider , InputModality , Model , ModelId , ModelSource , ProviderId , ProviderResponse , } ; use forge_domain :: Provider ; use pretty_assertions :: assert_eq ; use url :: Url ; use super :: * ; use crate :: display_constants :: markers ; impl AppCommand { pub fn name (& self) -> & str { match self { AppCommand :: Compact => "compact" , AppCommand :: New => "new" , AppCommand :: Message (_) => "message" , AppCommand :: Update => "update" , AppCommand :: Info => "info" , AppCommand :: Usage => "usage" , AppCommand :: Exit => "exit" , AppCommand :: Forge => "forge" , AppCommand :: Muse => "muse" , AppCommand :: Sage => "sage" , AppCommand :: Help => "help" , AppCommand :: Commit { .. } => "commit" , AppCommand :: Dump { .. } => "dump" , AppCommand :: Model => "model" , AppCommand :: Tools => "tools" , AppCommand :: Custom (event) => & event . name , AppCommand :: Shell (_) => "!shell" , AppCommand :: Agent => "agent" , AppCommand :: Login => "login" , AppCommand :: Logout => "logout" , AppCommand :: Retry => "retry" , AppCommand :: Conversations { .. } => "conversation" , AppCommand :: Delete => "delete" , AppCommand :: Rename { .. } => "rename" , AppCommand :: AgentSwitch (agent_id) => agent_id , AppCommand :: Index => "index" , AppCommand :: Config => "config" , AppCommand :: ConfigModel => "config-model" , AppCommand :: ConfigReload => "config-reload" , AppCommand :: ReasoningEffort => "reasoning-effort" , AppCommand :: ConfigReasoningEffort => "config-reasoning-effort" , AppCommand :: ConfigCommitModel => "config-commit-model" , AppCommand :: ConfigSuggestModel => "config-suggest-model" , AppCommand :: ConfigEdit => "config-edit" , AppCommand :: Skill => "skill" , AppCommand :: Edit { .. } => "edit" , AppCommand :: CommitPreview => "commit-preview" , AppCommand :: Suggest { .. } => "suggest" , AppCommand :: Clone { .. } => "clone" , AppCommand :: ConversationRename { .. } => "conversation-rename" , AppCommand :: Copy => "copy" , AppCommand :: WorkspaceSync => "workspace-sync" , AppCommand :: WorkspaceStatus => "workspace-status" , AppCommand :: WorkspaceInfo => "workspace-info" , AppCommand :: WorkspaceInit => "workspace-init" , AppCommand :: ModelTest => "model-test" , } } # [doc = " Returns the usage description for the command."] pub fn usage (& self) -> & str { self . get_str ("usage") . unwrap () } # [doc = " Returns true for internal/meta variants that should not appear in the"] # [doc = " public `forge list commands` output or the REPL help listing."] pub fn is_internal (& self) -> bool { matches ! (self , AppCommand :: Message (_) | AppCommand :: Custom (_) | AppCommand :: Shell (_) | AppCommand :: AgentSwitch (_) | AppCommand :: Rename { .. }) } # [doc = " Returns true for variants that are pure agent-switch shorthands whose"] # [doc = " canonical name matches a built-in agent (forge, muse, sage).  These"] # [doc = " commands are already emitted as AGENT rows by the agent-info loop in"] # [doc = " `on_show_commands`, so they must be excluded from the COMMAND loop to"] # [doc = " avoid duplicate entries in `list commands --porcelain`."] pub fn is_agent_switch (& self) -> bool { matches ! (self , AppCommand :: Forge | AppCommand :: Muse | AppCommand :: Sage) } }